        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def contains_substring(fib_num, sub_str):
    fib_str = str(fib_num)
    return sub_str in fib_str[-18:]

def find_arithmetic_sequence(n, a, d):
    def check(b, e):
        for i in range(n):
            fib_num = fibonacci(b + i * e)
            sub_str = str(a + i * d)
            if not contains_substring(fib_num, sub_str):
                return False
        return True

    # Binary search for b and e
    low_b, high_b = 1, 2**63 - 1
    low_e, high_e = 1, 2**63 - 1

    while low_b <= high_b:
        mid_b = (low_b + high_b) // 2
        if check(mid_b, 1):
            b = mid_b
            break
        elif fibonacci(mid_b) < a:
            low_b = mid_b + 1
        else:
            high_b = mid_b - 1

    if low_b > high_b:
        return -1

    while low_e <= high_e:
        mid_e = (low_e + high_e) // 2
